```python
def longest_common_subsequence(str1, str2):
    m, n = len(str1), len(str2)
    # Initialize a 2D array to store the LCS lengths
    lcs_lengths = [[0] * n for _ in range(m)]

    # Fill the array using dynamic programming
    for I in range(m):
        for j in range(n):
            if I == 0 or j == 0:
                lcs_lengths[i][j] = 0
            elif str1[i] == str2[j]:
                lcs_lengths[i][j] = lcs_lengths[i-1][j-1] + 1
            else:
                lcs_lengths[i][j] = max(lcs_lengths[i-1][j], lcs_lengths[i][j-1])

    # Find the LCS itself by backtracking through the array
    result = []
    I, j = m - 1, n - 1
    while I >= 0 and j >= 0:
        if I == 0 or j == 0:
            break
        elif str1[i] == str2[j]:
            result.append(str1[i])
            I -= 1
            j -= 1
        elif lcs_lengths[i-1][j] > lcs_lengths[i][j-1]:
            I -= 1
        else:
            j -= 1

    # Reverse the result (LCS is constructed in reverse order)
    result.reverse()
    return ''.join(result)
```

